// Calculate last week's date range
const now = new Date();
const lastWeek = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const lastWeekStart = lastWeek.toISOString().split('T')[0];
const lastWeekEnd = now.toISOString().split('T')[0];

// Extract data from previous nodes
const commits = $input.first().json;
const issues = $input.all()[1].json;
const prs = $input.all()[2].json;

// Filter only merged PRs
const mergedPRs = Array.isArray(prs) ? prs.filter(pr => pr.merged_at !== null) : [];

// Build summary context
const summaryContext = {
  period: { start: lastWeekStart, end: lastWeekEnd },
  repo: $env.GITHUB_REPO,
  commits_count: Array.isArray(commits) ? commits.length : 0,
  commits: Array.isArray(commits) ? commits.slice(0, 20).map(c => ({ sha: c.sha?.substring(0,7), message: c.commit?.message?.split('\n')[0], author: c.commit?.author?.name })) : [],
  issues_count: Array.isArray(issues) ? issues.length : 0,
  issues: Array.isArray(issues) ? issues.slice(0, 15).map(i => ({ number: i.number, title: i.title, state: i.state })) : [],
  prs_count: mergedPRs.length,
  prs: mergedPRs.slice(0, 15).map(pr => ({ number: pr.number, title: pr.title, merged_at: pr.merged_at }))
};

return [{ json: summaryContext }];

// Extract the Claude response text
const claudeResponse = $input.first().json;
const content = claudeResponse.content;

let summaryText = '';
if (Array.isArray(content)) {
  for (const block of content) {
    if (block.type === 'text') {
      summaryText = block.text;
      break;
    }
  }
} else if (typeof content === 'string') {
  summaryText = content;
}

return [{ json: { summary: summaryText, period: $vars.period || 'this week', repo: $env.GITHUB_REPO } }];
